* { box-sizing: border-box; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  margin: 0; color: #1a1a1a; background: #fafafa;
}
main { max-width: 760px; margin: 0 auto; padding: 32px 20px 64px; }
h1 { font-size: 22px; margin: 0 0 20px; }

.save-box { background: #fff; border: 1px solid #e2e2e2; border-radius: 10px; padding: 16px; margin-bottom: 18px; }
.save-box label { display: block; font-size: 12px; color: #666; margin: 0 0 4px; }
.save-box input { width: 100%; padding: 10px 12px; font-size: 14px; border: 1px solid #d5d5d5; border-radius: 7px; margin-bottom: 12px; }
.save-box button { background: #2563eb; color: #fff; border: 0; border-radius: 7px; padding: 10px 18px; font-size: 14px; font-weight: 600; cursor: pointer; }
.save-box button:hover { background: #1d4ed8; }

.hint { font-size: 12px; margin: -8px 0 12px; min-height: 16px; }
.hint.working { color: #999; }
.hint.warn { color: #b45309; }
.hint.ok { color: #999; }

.tagfield { border: 1px solid #d5d5d5; border-radius: 7px; padding: 6px 8px; margin-bottom: 6px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; background: #fff; }
.tagfield .pill { background: #4338ca; color: #fff; font-size: 12px; padding: 3px 8px 3px 10px; border-radius: 20px; display: inline-flex; align-items: center; gap: 6px; }
.tagfield .pill b { cursor: pointer; font-weight: 700; }
.tagfield input { border: 0; outline: 0; flex: 1; min-width: 120px; padding: 6px 2px; margin: 0; font-size: 14px; }

.suggest { margin: 0 0 12px; min-height: 22px; }
.suggest .s { display: inline-block; font-size: 12px; padding: 3px 10px; border-radius: 20px; border: 1px dashed #a5b4fc; color: #4338ca; background: #eef2ff; cursor: pointer; margin: 0 6px 6px 0; }
.suggest .s .new { color: #16a34a; font-weight: 600; }

.banner-slot:not(:empty) { margin-bottom: 12px; }
.banner { border-radius: 8px; padding: 10px 12px; font-size: 13px; }
.banner.dup { background: #fff7ed; border: 1px solid #fed7aa; color: #9a3412; }
.banner.bad { background: #fef2f2; border: 1px solid #fecaca; color: #b91c1c; }
.banner a { color: inherit; font-weight: 600; cursor: pointer; }

.search input { width: 100%; padding: 11px 14px; font-size: 15px; border: 1px solid #d5d5d5; border-radius: 9px; margin-bottom: 14px; }
.search input:disabled { background: #f4f4f4; color: #aaa; }

.tagbar { margin: 0 0 14px; max-height: 96px; overflow-y: auto; }
.tagbar:empty { display: none; }
.chip { display: inline-block; font-size: 12px; padding: 5px 12px; border-radius: 20px; border: 1px solid #d5d5d5; background: #fff; color: #333; cursor: pointer; margin: 0 6px 8px 0; }
.chip:hover { border-color: #2563eb; }
.chip.active { background: #2563eb; color: #fff; border-color: #2563eb; font-weight: 600; }

.count { font-size: 12px; color: #888; margin: 0 0 10px; }

ul.list { list-style: none; padding: 0; margin: 0; }
ul.list li { background: #fff; border: 1px solid #e2e2e2; border-radius: 10px; padding: 14px 16px; margin-bottom: 10px; }
ul.list li.flash { border-color: #2563eb; box-shadow: 0 0 0 3px #dbeafe; }
li .title {
  font-size: 15px; font-weight: 600; margin: 0 0 4px;
  display: -webkit-box; -webkit-line-clamp: 2; line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
li a.link {
  color: #2563eb; text-decoration: none; font-size: 13px;
  display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 8px;
}
li a.link:hover { text-decoration: underline; }
.itemtag { display: inline-block; font-size: 11px; background: #eef2ff; color: #4338ca; padding: 1px 8px; border-radius: 20px; margin-right: 5px; }
mark { background: #fde68a; padding: 0 1px; border-radius: 2px; }

.welcome { text-align: center; padding: 44px 24px; color: #666; }
.welcome .big { font-size: 40px; margin-bottom: 12px; }
.welcome h2 { font-size: 17px; margin: 0 0 8px; color: #333; }
.welcome p { font-size: 14px; margin: 0; line-height: 1.55; }
.welcome .arrow { margin-top: 16px; font-size: 13px; color: #2563eb; }
.no-match { color: #999; font-size: 14px; padding: 24px 0; text-align: center; }

